from .repository import put_contact

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _validate_batch(rows):
    if not isinstance(rows, list):
        raise ValueError("rows must be a list of contact objects")
    validated = []
    seen = set()
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("each contact row must be an object")
        if set(row.keys()) != {"email", "name"}:
            raise ValueError("each contact row must have exactly email and name")
        email = row["email"]
        name = row["name"]
        if not isinstance(email, str) or not isinstance(name, str):
            raise ValueError("email and name must be strings")
        email = email.strip()
        name = name.strip()
        if email.count("@") != 1:
            raise ValueError("email must contain exactly one '@'")
        if any(char.isspace() for char in email):
            raise ValueError("email must not contain whitespace")
        local, _, domain = email.partition("@")
        if not local or not domain:
            raise ValueError("email must have nonempty local part and domain")
        if not name:
            raise ValueError("name must be nonempty")
        email = email.lower()
        if email in seen:
            raise ValueError("duplicate email in batch: %s" % email)
        seen.add(email)
        validated.append((email, name))
    return validated

def import_contacts(connection, rows):
    validated = _validate_batch(rows)
    if not validated:
        return {"inserted": 0, "updated": 0}
    inserted = 0
    updated = 0
    try:
        for email, name in validated:
            exists = connection.execute(
                "SELECT 1 FROM contacts WHERE email = ?", (email,)
            ).fetchone() is not None
            put_contact(connection, email, name)
            if exists:
                updated += 1
            else:
                inserted += 1
        connection.commit()
    except Exception:
        connection.rollback()
        raise
    return {"inserted": inserted, "updated": updated}
